BEGIN;

UPDATE public.questions q
SET explanation_data = q.explanation_data || jsonb_build_object('viz', v.viz)
FROM (VALUES
  ('g-kentei-k-q21', '<svg viewBox="0 0 340 150" xmlns="http://www.w3.org/2000/svg"><text x="170" y="18" text-anchor="middle" font-size="11" fill="#8892a4">固有ベクトル：変換しても向きは同じ</text><line x1="170" y1="30" x2="170" y2="130" stroke="#2a2f3f" stroke-width="1"/><line x1="70" y1="80" x2="270" y2="80" stroke="#2a2f3f" stroke-width="1"/><line x1="170" y1="80" x2="215" y2="50" stroke="#8892a4" stroke-width="1.5" marker-end="url(#a1)"/><text x="178" y="45" font-size="9" fill="#8892a4">元</text><line x1="170" y1="80" x2="245" y2="35" stroke="#3b82f6" stroke-width="2" marker-end="url(#a2)"/><text x="245" y="30" text-anchor="middle" font-size="9" fill="#3b82f6">変換後（同じ向き）</text><line x1="170" y1="80" x2="200" y2="65" stroke="#8892a4" stroke-width="1.5" marker-end="url(#a1)"/><text x="135" y="60" font-size="9" fill="#8892a4">別のベクトル</text><line x1="170" y1="80" x2="140" y2="110" stroke="#c9a04a" stroke-width="2" marker-end="url(#a3)"/><text x="100" y="122" font-size="9" fill="#c9a04a">変換後（向きが変わる）</text><defs><marker id="a1" markerWidth="6" markerHeight="6" refX="5" refY="3" orient="auto"><path d="M0,0 L6,3 L0,6 Z" fill="#8892a4"/></marker><marker id="a2" markerWidth="6" markerHeight="6" refX="5" refY="3" orient="auto"><path d="M0,0 L6,3 L0,6 Z" fill="#3b82f6"/></marker><marker id="a3" markerWidth="6" markerHeight="6" refX="5" refY="3" orient="auto"><path d="M0,0 L6,3 L0,6 Z" fill="#c9a04a"/></marker></defs></svg>'),
  ('g-kentei-k-q9', '<svg viewBox="0 0 340 140" xmlns="http://www.w3.org/2000/svg"><text x="170" y="18" text-anchor="middle" font-size="11" fill="#8892a4">均等 vs 偏り：エントロピーの大小</text><text x="80" y="34" text-anchor="middle" font-size="9" fill="#60a5fa">均等（エントロピー大）</text><rect x="35" y="55" width="14" height="45" fill="#3b82f6"/><rect x="55" y="55" width="14" height="45" fill="#3b82f6"/><rect x="75" y="55" width="14" height="45" fill="#3b82f6"/><rect x="95" y="55" width="14" height="45" fill="#3b82f6"/><rect x="115" y="55" width="14" height="45" fill="#3b82f6"/><line x1="30" y1="100" x2="135" y2="100" stroke="#2a2f3f"/><text x="255" y="44" text-anchor="middle" font-size="9" fill="#c9a04a">偏り（エントロピー小）</text><rect x="210" y="95" width="14" height="5" fill="#c9a04a"/><rect x="230" y="50" width="14" height="50" fill="#c9a04a"/><rect x="250" y="98" width="14" height="2" fill="#c9a04a"/><rect x="270" y="99" width="14" height="1" fill="#c9a04a"/><rect x="290" y="99" width="14" height="1" fill="#c9a04a"/><line x1="205" y1="100" x2="310" y2="100" stroke="#2a2f3f"/></svg>')
) AS v(source_ref, viz)
WHERE q.source_ref = v.source_ref
  AND q.subject_id = (SELECT id FROM public.subjects WHERE slug = 'g-kentei-k');

COMMIT;
